// Package fakecf is a fake Cloudflare API for the cloudflare provider's tests. It serves seeded
// fixtures for the read operations the provider calls, and validates every fixture and every
// response against Cloudflare's Forge spec.
//
// fakecf_gen.json is generated by tools/forge-fakecf (make gen-cloudflare-fake): it holds each
// operation's parameters and response type, and the models they reach. This file interprets it.
package fakecf

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"math"
	"regexp"
	"sort"
	"strings"
	"time"
)

//go:embed fakecf_gen.json
var schemaJSON []byte

// typ is one type from fakecf_gen.json. K says which fields apply.
type typ struct {
	K string `json:"k"` // scalar, enum, array, object, union, all, ref

	S string `json:"s,omitempty"` // scalar: unknown, null, boolean, string, number, date-time, ...
	N string `json:"n,omitempty"` // scalar number format: int, int32, double, ...

	V []any `json:"v,omitempty"` // enum values

	E   *typ     `json:"e,omitempty"`   // array element
	Min *float64 `json:"min,omitempty"` // array minItems
	Max *float64 `json:"max,omitempty"` // array maxItems

	F []field `json:"f,omitempty"` // object fields
	X *typ    `json:"x,omitempty"` // object: type of other keys; nil allows none

	M    []*typ         `json:"m,omitempty"`    // union or intersection members
	Excl bool           `json:"excl,omitempty"` // union: oneOf
	D    *discriminator `json:"d,omitempty"`    // union discriminator

	R string `json:"r,omitempty"` // ref: model name
}

type field struct {
	W    string `json:"w"`
	T    *typ   `json:"t"`
	Req  bool   `json:"req,omitempty"`
	Sens bool   `json:"sens,omitempty"`
}

type discriminator struct {
	W string          `json:"w"`
	C map[string]*typ `json:"c"`
}

type param struct {
	Name string `json:"name"`
	T    *typ   `json:"t"`
}

// operation is one API operation the fake serves.
type operation struct {
	Method      string  `json:"method"`
	Path        string  `json:"path"`
	PathParams  []param `json:"pathParams"`
	QueryParams []param `json:"queryParams"`
	Response    *typ    `json:"response"`

	segments []string
	list     bool // the response is {result: [...], result_info}
	paging   string
	elem     *typ // list: the type of one result item
	info     *typ // list: the type of result_info, or nil
	empty    any  // not a list: the result when nothing is seeded, or nil for a 404
}

const (
	pagingNone   = "none"
	pagingPage   = "page"
	pagingCursor = "cursor"
)

// Key is the operation's "METHOD path".
func (op *operation) Key() string { return op.Method + " " + op.Path }

type schema struct {
	SpecVersion string                `json:"specVersion"`
	Operations  []*operation          `json:"operations"`
	Models      map[string]*typ       `json:"models"`
	byKey       map[string]*operation `json:"-"`
}

func loadSchema() (*schema, error) {
	var s schema
	if err := json.Unmarshal(schemaJSON, &s); err != nil {
		return nil, fmt.Errorf("fakecf_gen.json: %w", err)
	}
	s.byKey = make(map[string]*operation, len(s.Operations))
	for _, op := range s.Operations {
		op.segments = strings.Split(strings.Trim(op.Path, "/"), "/")
		s.classify(op)
		s.byKey[op.Key()] = op
	}
	return &s, nil
}

// classify works out whether op returns a list, how it pages, and its item type.
func (s *schema) classify(op *operation) {
	op.paging = pagingNone
	fields, _ := s.objectFields(op.Response)
	result, ok := fields["result"]
	if !ok || !result.Req {
		op.empty = s.emptyCollection(fields)
		return
	}
	resultType := s.resolve(result.T)
	if resultType.K != "array" {
		return
	}
	op.list = true
	op.elem = resultType.E
	if info, ok := fields["result_info"]; ok {
		op.info = info.T
	}
	for _, q := range op.QueryParams {
		switch q.Name {
		case "page":
			op.paging = pagingPage
		case "cursor":
			if op.paging == pagingNone {
				op.paging = pagingCursor
			}
		}
	}
}

// emptyCollection returns the value of an object whose required fields are all arrays, such as
// R2's {"buckets": [...]}, with each array empty: what an account with none of them gets. It
// returns nil for anything else, which is answered with a 404 when nothing is seeded.
func (s *schema) emptyCollection(fields map[string]field) any {
	empty := map[string]any{}
	for name, f := range fields {
		if !f.Req {
			continue
		}
		if t := s.resolve(f.T); t == nil || t.K != "array" {
			return nil
		}
		empty[name] = []any{}
	}
	if len(empty) == 0 {
		return nil
	}
	return empty
}

// resolve follows refs to the type they name.
func (s *schema) resolve(t *typ) *typ {
	for i := 0; t != nil && t.K == "ref"; i++ {
		if i > 64 {
			panic("fakecf: ref chain too long at " + t.R)
		}
		t = s.Models[t.R]
	}
	return t
}

// objectFields returns the fields an object, ref, or intersection of objects declares, and
// whether it allows other keys. Union members contribute their fields too, so keys any member
// allows are known.
func (s *schema) objectFields(t *typ) (map[string]field, bool) {
	fields := map[string]field{}
	open := s.collectFields(t, fields, 0)
	return fields, open
}

func (s *schema) collectFields(t *typ, into map[string]field, depth int) (open bool) {
	if depth > 32 {
		return true
	}
	t = s.resolve(t)
	if t == nil {
		return true
	}
	switch t.K {
	case "object":
		for _, f := range t.F {
			if prev, ok := into[f.W]; !ok || (f.Req && !prev.Req) {
				into[f.W] = f
			}
		}
		return t.X != nil
	case "all", "union":
		for _, m := range t.M {
			if s.collectFields(m, into, depth+1) {
				open = true
			}
		}
		return open
	case "scalar":
		return t.S == "unknown"
	}
	return false
}

var (
	uuidDashed = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)
	uuidPlain  = regexp.MustCompile(`^[0-9a-fA-F]{32}$`)
)

// validator collects every violation of one value, each prefixed with its JSON path.
type validator struct {
	s    *schema
	errs []string
}

// validate checks v (decoded with UseNumber) against t. strict reports object keys the type
// doesn't declare; an intersection checks its members leniently and its keys once, together.
func (v *validator) validate(t *typ, value any, path string, strict bool) {
	if t == nil {
		return
	}
	switch t.K {
	case "ref":
		v.validate(v.s.Models[t.R], value, path, strict)
	case "scalar":
		v.scalar(t, value, path)
	case "enum":
		for _, want := range t.V {
			if enumEqual(want, value) {
				return
			}
		}
		v.errorf(path, "%s is not one of %v", show(value), t.V)
	case "array":
		v.array(t, value, path, strict)
	case "object":
		v.object(t, value, path, strict)
	case "all":
		for _, m := range t.M {
			v.validate(m, value, path, false)
		}
		if obj, ok := value.(map[string]any); ok && strict {
			v.unknownKeys(t, obj, path)
		}
	case "union":
		v.union(t, value, path, strict)
	default:
		v.errorf(path, "schema has unknown type kind %q", t.K)
	}
}

func (v *validator) errorf(path, format string, args ...any) {
	if path == "" {
		path = "$"
	}
	v.errs = append(v.errs, path+": "+fmt.Sprintf(format, args...))
}

func (v *validator) scalar(t *typ, value any, path string) {
	switch t.S {
	case "unknown":
	case "null":
		if value != nil {
			v.errorf(path, "%s is not null", show(value))
		}
	case "boolean":
		if _, ok := value.(bool); !ok {
			v.errorf(path, "%s is not a boolean", show(value))
		}
	case "number":
		n, ok := value.(json.Number)
		if !ok {
			v.errorf(path, "%s is not a number", show(value))
			return
		}
		f, err := n.Float64()
		if err != nil {
			v.errorf(path, "%s is not a number", n)
			return
		}
		if t.N != "" && t.N != "float" && t.N != "double" && f != math.Trunc(f) {
			v.errorf(path, "%s is not an integer (%s)", n, t.N)
		}
	default: // string, date-time, date, bytes, binary, uuid
		str, ok := value.(string)
		if !ok {
			v.errorf(path, "%s is not a string (%s)", show(value), t.S)
			return
		}
		v.stringFormat(t.S, str, path)
	}
}

func (v *validator) stringFormat(format, str, path string) {
	switch format {
	case "date-time":
		if _, err := time.Parse(time.RFC3339Nano, str); err != nil {
			v.errorf(path, "%q is not an RFC 3339 date-time", str)
		}
	case "date":
		if _, err := time.Parse(time.DateOnly, str); err != nil {
			v.errorf(path, "%q is not a date", str)
		}
	case "uuid":
		// Cloudflare writes many of its 32-hex-digit IDs as format uuid.
		if !uuidDashed.MatchString(str) && !uuidPlain.MatchString(str) {
			v.errorf(path, "%q is not a uuid", str)
		}
	}
}

func (v *validator) array(t *typ, value any, path string, strict bool) {
	items, ok := value.([]any)
	if !ok {
		v.errorf(path, "%s is not an array", show(value))
		return
	}
	if t.Min != nil && float64(len(items)) < *t.Min {
		v.errorf(path, "has %d items, fewer than %v", len(items), *t.Min)
	}
	if t.Max != nil && float64(len(items)) > *t.Max {
		v.errorf(path, "has %d items, more than %v", len(items), *t.Max)
	}
	for i, item := range items {
		v.validate(t.E, item, fmt.Sprintf("%s[%d]", orRoot(path), i), strict)
	}
}

func (v *validator) object(t *typ, value any, path string, strict bool) {
	obj, ok := value.(map[string]any)
	if !ok {
		v.errorf(path, "%s is not an object", show(value))
		return
	}
	declared := make(map[string]bool, len(t.F))
	for _, f := range t.F {
		declared[f.W] = true
		fv, present := obj[f.W]
		if !present {
			if f.Req {
				v.errorf(join(path, f.W), "required property is missing")
			}
			continue
		}
		v.validate(f.T, fv, join(path, f.W), true)
	}
	keys := sortedKeys(obj)
	for _, key := range keys {
		if declared[key] {
			continue
		}
		if t.X != nil {
			v.validate(t.X, obj[key], join(path, key), true)
		} else if strict {
			v.errorf(join(path, key), "property is not in the schema")
		}
	}
}

func (v *validator) unknownKeys(t *typ, obj map[string]any, path string) {
	known, open := v.s.objectFields(t)
	if open {
		return
	}
	for _, key := range sortedKeys(obj) {
		if _, ok := known[key]; !ok {
			v.errorf(join(path, key), "property is not in the schema")
		}
	}
}

// union passes when the value matches the discriminated case, or else any member. On failure it
// reports the member that came closest.
func (v *validator) union(t *typ, value any, path string, strict bool) {
	if t.D != nil {
		if obj, ok := value.(map[string]any); ok {
			if tag, ok := obj[t.D.W].(string); ok {
				if member, ok := t.D.C[tag]; ok {
					v.validate(member, value, path, strict)
					return
				}
			}
		}
	}
	var best []string
	for _, member := range t.M {
		sub := validator{s: v.s}
		sub.validate(member, value, path, strict)
		if len(sub.errs) == 0 {
			return
		}
		if best == nil || len(sub.errs) < len(best) {
			best = sub.errs
		}
	}
	v.errorf(path, "matches none of the %d union members; closest:", len(t.M))
	for _, e := range best {
		v.errs = append(v.errs, "  "+e)
	}
}

func enumEqual(want, got any) bool {
	switch w := want.(type) {
	case string:
		g, ok := got.(string)
		return ok && g == w
	case bool:
		g, ok := got.(bool)
		return ok && g == w
	case float64:
		g, ok := got.(json.Number)
		if !ok {
			return false
		}
		f, err := g.Float64()
		return err == nil && f == w
	}
	return false
}

func show(value any) string {
	data, err := json.Marshal(value)
	if err != nil {
		return fmt.Sprintf("%v", value)
	}
	if len(data) > 60 {
		return string(data[:57]) + "..."
	}
	return string(data)
}

func join(path, key string) string { return orRoot(path) + "." + key }

func orRoot(path string) string {
	if path == "" {
		return "$"
	}
	return path
}

func sortedKeys(obj map[string]any) []string {
	keys := make([]string, 0, len(obj))
	for key := range obj {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}
